<script>
document.addEventListener('DOMContentLoaded',function(){
var csrf=document.querySelector('meta[name="csrf-token"]').content,previewUrl=@json(route('admin.moodle-sync.preview')),startUrl=@json(route('admin.moodle-sync.start')),testUrl=@json(route('admin.moodle-sync.test')),progressUrl=@json(route('admin.moodle-sync.progress',['run'=>'__RUN__']));
var labels={users:'User',cohorts:'Kohor dan rombel',categories:'Kategori akademik',all:'Semua domain'},fmt=function(v){return new Intl.NumberFormat('id-ID').format(v||0)},notify=function(t,m){if(window.toastr&&typeof window.toastr[t]==='function')window.toastr[t](m);else window.alert(m)};
var post=function(url,body){return fetch(url,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify(body||{})}).then(function(r){return r.json().then(function(d){if(!r.ok)throw new Error(d.message||'Permintaan gagal.');return d})})};
var modal=function(o){return window.Swal?window.Swal.fire(o):Promise.resolve({isConfirmed:window.confirm(o.text||o.title||'Lanjutkan?')})};
var progress=function(stage,pct,log){return '<div class="live-stage mb-2">'+stage+'</div><div class="progress mb-2"><div class="progress-bar" style="width:'+pct+'%">'+pct+'%</div></div><div class="live-count small text-muted">0 item</div><div class="live-log mt-3">['+pct+'%] '+log+'</div>'};
var update=function(d){var b=window.Swal&&window.Swal.getHtmlContainer?window.Swal.getHtmlContainer():null;if(!b)return;var bar=b.querySelector('.progress-bar'),st=b.querySelector('.live-stage'),co=b.querySelector('.live-count'),lo=b.querySelector('.live-log');if(bar){bar.style.width=d.percent+'%';bar.textContent=d.percent+'%'}if(st)st.textContent=d.stage||'Memproses';if(co)co.textContent=fmt(d.processed)+' / '+fmt(d.total)+' item';if(lo)lo.innerHTML='['+d.percent+'%] '+(d.stage||'Memproses')+'<br>'+lo.innerHTML};
var watch=function(id){fetch(progressUrl.replace('__RUN__',id),{headers:{Accept:'application/json'}}).then(function(r){return r.json()}).then(function(d){update(d);if(d.status==='success'||d.status==='failed'){if(window.Swal)window.Swal.close();notify(d.status==='success'?'success':'error',d.status==='success'?'Rekonsiliasi selesai.':(d.error||'Rekonsiliasi gagal.'));setTimeout(function(){location.reload()},700)}else setTimeout(function(){watch(id)},1200)}).catch(function(){setTimeout(function(){watch(id)},2500)})};
var begin=function(type,token){post(startUrl,{type:type,preview_token:token,confirmed:true}).then(function(d){if(window.Swal)window.Swal.fire({title:'Rekonsiliasi berjalan',html:progress('Menunggu worker',0,'Perubahan masuk antrean'),allowOutsideClick:false,showConfirmButton:false});watch(d.run_id)}).catch(function(e){notify('error',e.message)})};
document.getElementById('moodle-test-connection').addEventListener('click',function(){modal({icon:'question',title:'Tes koneksi Moodle?',text:'Tes koneksi hanya membaca informasi situs.',showCancelButton:true,confirmButtonText:'Ya, tes koneksi',cancelButtonText:'Batal'}).then(function(r){if(!r.isConfirmed)return;if(window.Swal)window.Swal.fire({title:'Menguji koneksi',html:progress('Web Service Moodle',25,'Permintaan dikirim'),allowOutsideClick:false,showConfirmButton:false});post(testUrl).then(function(d){modal({icon:'success',title:'Koneksi berhasil',text:d.message,confirmButtonText:'Tutup'})}).catch(function(e){modal({icon:'error',title:'Koneksi gagal',text:e.message})})})});
document.querySelectorAll('.sync-preview').forEach(function(btn){btn.addEventListener('click',function(){var type=btn.dataset.type;if(window.Swal)window.Swal.fire({title:'Membandingkan '+labels[type],html:progress('Membaca SIMANSA dan Moodle',10,'Menyusun perbedaan read-only'),allowOutsideClick:false,showConfirmButton:false});post(previewUrl,{type:type}).then(function(d){var a=d.actions,p=d.preview,details=d.plan.cohorts&&d.plan.cohorts.details||{},rows=Object.keys(details).map(function(k){var x=details[k],act=x.metadata_action==='create'?'Buat kohor':(x.metadata_action==='update'?'Perbarui kohor':'Sama');return '<tr><td>'+x.idnumber+'</td><td>'+x.local_name+'</td><td>'+(x.moodle_name||'<em>Belum ada</em>')+'</td><td>'+act+'</td><td>'+fmt(x.local_members)+' / '+fmt(x.moodle_members)+'</td><td>'+fmt(x.membership_add)+'</td></tr>'}).join(''),table=type==='cohorts'?'<div class="table-responsive mt-3" style="max-height:280px"><table class="table table-sm text-left"><thead><tr><th>ID</th><th>SIMANSA</th><th>Moodle</th><th>Status</th><th>Anggota S/M</th><th>Tambah</th></tr></thead><tbody>'+rows+'</tbody></table></div>':'',html='<div class="row text-center"><div class="col-6"><strong class="d-block h4">'+fmt(p.students+p.gtk)+'</strong><small>User SIMANSA</small></div><div class="col-6"><strong class="d-block h4">'+fmt(p.cohorts)+'</strong><small>Rombel aktif</small></div></div><div class="alert alert-warning mt-3 text-left"><b>Rencana perubahan</b><br>Buat: <strong>'+fmt(a.create)+'</strong> · Perbarui: <strong>'+fmt(a.update)+'</strong> · Masuk kohor: <strong>'+fmt(a.membership_add)+'</strong> · Keluar kohor: <strong>'+fmt(a.membership_remove)+'</strong><br>Tidak berubah: <strong>'+fmt(a.unchanged)+'</strong><br><small>Preview tidak menulis Moodle. Data manual dan objek non-SIMANSA tidak disentuh.</small></div>'+table;return modal({icon:'info',title:'Preview '+labels[type],html:html,showCancelButton:true,confirmButtonText:'Lanjutkan',cancelButtonText:'Batal'}).then(function(r){if(!r.isConfirmed||!d.comparison_complete)return null;var check='<div class="text-left"><p>Pastikan rencana perubahan sudah diperiksa.</p><label><input id="moodle-confirm-checkbox" type="checkbox" style="margin-right:8px"> Saya menyetujui perubahan yang tampil pada preview.</label></div>';return modal({icon:'warning',title:'Konfirmasi perubahan Moodle',html:check,showCancelButton:true,confirmButtonText:'Ya, mulai',cancelButtonText:'Batal',focusConfirm:false,didOpen:function(){var c=window.Swal.getConfirmButton();c.disabled=true;document.getElementById('moodle-confirm-checkbox').onchange=function(){c.disabled=!this.checked}},preConfirm:function(){if(!document.getElementById('moodle-confirm-checkbox').checked){window.Swal.showValidationMessage('Persetujuan wajib dicentang.');return false}return true}}).then(function(x){if(x.isConfirmed)begin(type,d.preview_token)})})}).catch(function(e){modal({icon:'error',title:'Preview gagal',text:e.message})})})});
});
</script>
